import json
from pathlib import Path

from datetime import datetime, timezone

UTC = timezone.utc

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


def _parse_bound_with_policy(value):
    raw = datetime.fromisoformat(value)
    return parse_bound(value), raw.tzinfo is None


def _parse_error(param, payload, exc):
    return build_rejection(
        param,
        f"must be a valid ISO 8601 timestamp: {exc}",
        payload,
    )


def _normalized_report(start, end, start_was_naive=False, end_was_naive=False):
    """Return the values used for comparison, including the naive-time policy."""
    report = {
        "start_utc": start.astimezone(UTC).isoformat(),
        "end_utc": end.astimezone(UTC).isoformat(),
        "timezone_policy": (
            f"{MISSING_TZ_POLICY}: {DEFAULT_TIMEZONE.tzname(None)}"
        ),
    }
    if start_was_naive:
        report["start_assumed_timezone"] = DEFAULT_TIMEZONE.tzname(None)
    if end_was_naive:
        report["end_assumed_timezone"] = DEFAULT_TIMEZONE.tzname(None)
    return report


def validate_range(payload):
    errors = []
    start = end = None
    start_was_naive = end_was_naive = False

    if "start_date" not in payload:
        errors.append(build_rejection("start_date", "is required", payload))
    else:
        try:
            start, start_was_naive = _parse_bound_with_policy(payload["start_date"])
        except (TypeError, ValueError) as exc:
            errors.append(_parse_error("start_date", payload, exc))

    # end_date is intentionally optional. A start-only query is valid after
    # validating the start timestamp itself.
    if "end_date" in payload:
        try:
            end, end_was_naive = _parse_bound_with_policy(payload["end_date"])
        except (TypeError, ValueError) as exc:
            errors.append(_parse_error("end_date", payload, exc))

    if errors or end is None or start is None:
        return errors

    normalized = _normalized_report(
        start,
        end,
        start_was_naive,
        end_was_naive,
    )
    start_utc = start.astimezone(UTC)
    end_utc = end.astimezone(UTC)

    # The service defines the range by instants, so equality is valid and only
    # an end instant strictly before the start instant is rejected.
    if end_utc < start_utc:
        return [
            build_rejection(
                "date_range",
                (
                    "end must be on or after start after UTC normalization "
                    f"(start={normalized['start_utc']}, end={normalized['end_utc']})"
                ),
                payload,
                normalized,
            )
        ]

    # A fall-back overlap is treated as ambiguous local input by the service.
    # In particular, do not let UTC ordering accept 01:30 (first occurrence)
    # through 01:15 (second occurrence) on the same local date.
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    ):
        return [
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range: end wall-clock time is earlier than start",
                payload,
                normalized,
            )
        ]
    return []


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

